import { describe, expect, test, beforeEach } from "vitest";
import { adaptPatch, validatePatchTransplant, verifyBehaviorPreservation, mergeOrchestrationConfigs } from "./patch-orchestrator";

const PATCH_EXAMPLES = [
  {
    name: "simple_build_fix",
    source: "pareto-2080/rework-buildfail-qafix",
    similarity: 0.357,
    config: { task_class: "build", need: 6, risk: "standard" },
    expected_adaptation: { preserve_behavior: true }
  },
  {
    name: "orchestration_pipeline_contract",
    source: "deployfix-beethoven-07190257",
    similarity: 0.374,
    config: { task_class: "build", source: "native-claim", preflight_triage: "gemini-2.5-flash" },
    expected_adaptation: { preserve_behavior: true }
  },
  {
    name: "hard_task_with_broad_change_risk",
    source: "release-conflict-self-heal",
    similarity: 0.245,
    config: { task_class: "hard", need: 8, risk: "broad_change", agentic_coder: "claude-haiku-4-5-20251001" },
    expected_adaptation: { preserve_behavior: true, requires_qa_panel: true }
  }
];

describe("adaptPatch", () => {
  PATCH_EXAMPLES.forEach((example) => {
    test(`adapt patch from ${example.source} with similarity ${example.similarity}`, () => {
      const result = adaptPatch(example.source, example.config);
      expect(result).toBeDefined();
      expect(result.similarity).toBeGreaterThan(0);
      expect(result.adapted_config).toBeDefined();
    });
  });

  test("adapt patch with insufficient similarity should warn", () => {
    const config = { task_class: "build" };
    const result = adaptPatch("unknown-source", config);
    expect(result.warnings).toContain("low_similarity");
  });
});

describe("validatePatchTransplant", () => {
  PATCH_EXAMPLES.forEach((example) => {
    test(`validate transplant for ${example.name} preserves existing behavior`, () => {
      const transplant = adaptPatch(example.source, example.config);
      const validation = validatePatchTransplant(transplant);
      expect(validation.preserves_behavior).toBe(example.expected_adaptation.preserve_behavior);
      expect(validation.errors).toHaveLength(0);
    });
  });

  test("transplant without behavior preservation should fail validation", () => {
    const transplant = { config: {}, preserves_behavior: false };
    const validation = validatePatchTransplant(transplant);
    expect(validation.errors).toContain("behavior_not_preserved");
  });

  test("transplant with orphaned dependencies should be detected", () => {
    const transplant = { config: { depends_on: "missing-config-key" }, preserves_behavior: true };
    const validation = validatePatchTransplant(transplant);
    expect(validation.errors).toContain("unmet_dependency");
  });
});

describe("verifyBehaviorPreservation", () => {
  test("identical config should verify as preserved", () => {
    const original = { task_class: "build", need: 6 };
    const adapted = { task_class: "build", need: 6, additional_key: "value" };
    const result = verifyBehaviorPreservation(original, adapted);
    expect(result.preserved).toBe(true);
  });

  test("modified core task_class should fail preservation", () => {
    const original = { task_class: "build" };
    const adapted = { task_class: "hard" };
    const result = verifyBehaviorPreservation(original, adapted);
    expect(result.preserved).toBe(false);
    expect(result.modified_keys).toContain("task_class");
  });

  test("empty original config should verify new config", () => {
    const original = {};
    const adapted = { task_class: "build", need: 6 };
    const result = verifyBehaviorPreservation(original, adapted);
    expect(result.preserved).toBe(true);
  });
});

describe("mergeOrchestrationConfigs", () => {
  test("merge two compatible orchestration configs", () => {
    const config1 = { preflight_triage: "gemini-2.5-flash", task_class: "build" };
    const config2 = { strategy_planner: "deepseek-v4-flash" };
    const result = mergeOrchestrationConfigs(config1, config2);
    expect(result.preflight_triage).toBe("gemini-2.5-flash");
    expect(result.strategy_planner).toBe("deepseek-v4-flash");
    expect(result.task_class).toBe("build");
  });

  test("merge with conflicting keys should preserve acceptance criteria", () => {
    const config1 = { agentic_coder: "claude-haiku-4-5-20251001" };
    const config2 = { agentic_coder: "ollama" };
    const result = mergeOrchestrationConfigs(config1, config2);
    expect(result.conflict).toBeDefined();
    expect(result.conflict.keys).toContain("agentic_coder");
  });

  test("merge QA panel configurations", () => {
    const config1 = { qa_panel: ["llama3.2:3b"] };
    const config2 = { qa_panel: ["deepseek-v4-flash"] };
    const result = mergeOrchestrationConfigs(config1, config2);
    expect(result.qa_panel).toContain("llama3.2:3b");
    expect(result.qa_panel).toContain("deepseek-v4-flash");
  });
});

describe("edge cases", () => {
  test("adapt patch with null source", () => {
    const result = adaptPatch(null, { task_class: "build" });
    expect(result.errors).toBeDefined();
  });

  test("adapt patch with empty config", () => {
    const result = adaptPatch("known-source", {});
    expect(result).toBeDefined();
    expect(result.adapted_config).toBeDefined();
  });

  test("validate transplant with circular dependencies", () => {
    const transplant = { config: { depends_on: "self" }, preserves_behavior: true };
    const validation = validatePatchTransplant(transplant);
    expect(validation.errors).toContain("circular_dependency");
  });

  test("behavior preservation with deeply nested config", () => {
    const original = { orchestration: { pipeline: { contract: { task_class: "build" } } } };
    const adapted = { orchestration: { pipeline: { contract: { task_class: "build" }, extra: "field" } } };
    const result = verifyBehaviorPreservation(original, adapted);
    expect(result.preserved).toBe(true);
  });
});
